static void asset(struct json_object *a,const char *name,const char *role,const char *dtype,const void *data,size_t n,unsigned h,unsigned w){char sha[65];demo_sha_hex(data,n,sha);struct json_object *o=json_object_new_object(),*s=json_object_new_array();json_object_object_add(o,"name",json_object_new_string(name));json_object_object_add(o,"role",json_object_new_string(role));json_object_object_add(o,"dtype",json_object_new_string(dtype));json_object_object_add(o,"bytes",json_object_new_uint64(n));json_object_object_add(o,"sha256",json_object_new_string(sha));json_object_array_add(s,json_object_new_int(h));json_object_array_add(s,json_object_new_int(w));if(!strcmp(dtype,"FP32"))json_object_array_add(s,json_object_new_int(3));json_object_object_add(o,"shape",s);json_object_array_add(a,o);}
static void viewer_model(struct demo_store *store,const char *directory,struct demo_frame *frame){char path[108];snprintf(path,sizeof(path),"%s/viewer.sock",directory);int listener=socket(AF_UNIX,SOCK_STREAM,0);assert(listener>=0);struct sockaddr_un address={0};address.sun_family=AF_UNIX;strcpy(address.sun_path,path);assert(!bind(listener,(struct sockaddr*)&address,sizeof(address))&&!listen(listener,1));assert(!chmod(path,0600));pid_t child=fork();assert(child>=0);if(!child){alarm(5);int fd=accept(listener,NULL,NULL);char request[1024]={0};ssize_t n=read(fd,request,sizeof(request)-1);assert(n>0&&strstr(request,frame->run_id)&&strstr(request,frame->source_result_sha)&&strstr(request,frame->sha256));const char *reply="{\"exit\":0,\"scope\":\"DISPLAY_ONLY_NO_INFERENCE\"}\n";assert(write(fd,reply,strlen(reply))==(ssize_t)strlen(reply));close(fd);close(listener);_exit(0);}assert(!demo_send_display_reference(store,path,frame));int status=0;assert(waitpid(child,&status,0)==child&&WIFEXITED(status)&&!WEXITSTATUS(status));close(listener);assert(!unlink(path));}
int main(int argc,char **argv){assert(argc==2);char directory[]="/tmp/demo-prepare-XXXXXX";assert(mkdtemp(directory));struct demo_store store;assert(!demo_store_open(&store,directory,NULL));char *text=calloc(1,DEMO_MAX_JSON+1);struct demo_result *r=calloc(1,sizeof(*r));assert(text&&r);FILE *file=fopen(argv[1],"rb");assert(file);size_t n=fread(text,1,DEMO_MAX_JSON,file);fclose(file);struct json_object *o=json_tokener_parse(text),*a=json_object_new_array();unsigned char input[6]={0,255,0,0,0,255},output[6]={255,0,0,255,255,255};float logits[6]={1,2,3,4,5,6};asset(a,"frame-test-input.rgb","input","RGB8",input,6,1,2);asset(a,"frame-test-output.rgb","display","RGB8",output,6,1,2);asset(a,"frame-test-output.f32","output","FP32",logits,24,1,2);json_object_object_add(o,"artifacts",a);const char *raw=json_object_to_json_string_ext(o,JSON_C_TO_STRING_PLAIN);assert(!demo_parse_run(raw,strlen(raw),&r->run));json_object_put(o);assert(!demo_write_result(r,text,DEMO_MAX_JSON+1,&n));demo_sha_hex(text,n,r->source_result_sha);struct demo_frame frame={0};assert(demo_prepare_display(&store,r,DEMO_LAYOUT_COMPARE,&frame)<0);assert(!demo_store_run_asset(&store,r->run.run_id,"frame-test-input.rgb",input,6));assert(!demo_store_run_asset(&store,r->run.run_id,"frame-test-output.rgb",output,6));assert(!demo_store_run_asset(&store,r->run.run_id,"frame-test-output.f32",logits,24));assert(!demo_publish(&store,r));for(unsigned mode=1;mode<=3;++mode){assert(!demo_prepare_display(&store,r,(enum demo_layout)mode,&frame));assert(frame.width==1280&&frame.height==720&&!strcmp(frame.run_id,r->run.run_id)&&!strcmp(frame.source_result_sha,r->source_result_sha));assert(!demo_frame_publish(&store,&frame,r));if(mode==1)viewer_model(&store,directory,&frame);demo_frame_free(&frame);}/* Results remain immutable; changed file bytes are not shown as the frozen result. */char path[512];snprintf(path,sizeof(path),"%s/%s/frame-test-output.rgb",directory,r->run.run_id);int fd=open(path,O_WRONLY);assert(fd>=0&&write(fd,"!",1)==1);close(fd);assert(demo_prepare_display(&store,r,DEMO_LAYOUT_RESULT,&frame)==-EBADMSG&&!frame.pixels);demo_store_close(&store);free(text);free(r);puts("IMMUTABLE_DISPLAY_REHYDRATION_INPUT_RESULT_COMPARE_REJECTS_TAMPER_NO_GPU_NO_DRM");return 0;}
